files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-dark: #b8324a;
  --text: #eaeaea;
  --muted: #8a8a9a;
  --border: #0f3460;
  --font: 'Courier New', Courier, monospace;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #1a1a2e 25%, #1f1f3a 25%, #1f1f3a 50%, #1a1a2e 50%, #1a1a2e 75%, #1f1f3a 75%, #1f1f3a 100%);
  background-size: 40px 40px;
  font-family: var(--font);
  font-size: 16px;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.5);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.title {
  font-size: 1.25rem;
  letter-spacing: 2px;
  color: var(--accent);
  text-transform: uppercase;
}

.mode {
  font-size: 1rem;
  letter-spacing: 4px;
  color: var(--muted);
  text-transform: uppercase;
  border-bottom: 2px dashed var(--border);
  padding-bottom: 8px;
}

.timer {
  font-size: 4.5rem;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 4px 4px 0 var(--accent-dark);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: bold;
  letter-spacing: 2px;
  padding: 12px 20px;
  background: var(--accent);
  color: #fff;
  border: 3px solid var(--accent-dark);
  box-shadow: 4px 4px 0 var(--accent-dark);
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
  text-transform: uppercase;
  min-width: 110px;
}

.btn:hover {
  background: #f05a72;
}

.btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--accent-dark);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-btn {
  background: var(--border);
  border-color: #0a2540;
  box-shadow: 4px 4px 0 #0a2540;
  font-size: 0.875rem;
  min-width: 100px;
  padding: 10px 14px;
}

.mode-btn:hover {
  background: #1a4a7a;
}

.mode-btn.active {
  background: var(--accent);
  border-color: var(--accent-dark);
  box-shadow: 4px 4px 0 var(--accent-dark);
}

.mode-btn.active:hover {
  background: #f05a72;
}

.hint {
  font-size: 0.875rem;
  color: var(--muted);
  letter-spacing: 1px;
}

@media (max-width: 400px) {
  .timer {
    font-size: 3.5rem;
  }
  .card {
    padding: 24px 16px;
  }
  .btn {
    font-size: 0.875rem;
    padding: 10px 14px;
    min-width: 90px;
  }
}

const WORK_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;

const timerDisplay = document.getElementById('timer-display');
const modeIndicator = document.getElementById('mode-indicator');
const startPauseBtn = document.getElementById('start-pause-btn');
const resetBtn = document.getElementById('reset-btn');
const workModeBtn = document.getElementById('work-mode-btn');
const breakModeBtn = document.getElementById('break-mode-btn');

let mode = 'work';
let remaining = WORK_SECONDS;
let running = false;
let intervalId = null;
let endTime = 0;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(remaining);
  modeIndicator.textContent = mode === 'work' ? 'WORK' : 'BREAK';
  document.title = formatTime(remaining) + ' - ' + (mode === 'work' ? 'Work' : 'Break');
}

function setMode(newMode) {
  mode = newMode;
  remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
  stopTimer();
  updateDisplay();
  workModeBtn.classList.toggle('active', mode === 'work');
  breakModeBtn.classList.toggle('active', mode === 'break');
  workModeBtn.setAttribute('aria-pressed', mode === 'work');
  breakModeBtn.setAttribute('aria-pressed', mode === 'break');
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function tick() {
  const now = Date.now();
  const secondsLeft = Math.max(0, Math.round((endTime - now) / 1000));
  if (secondsLeft !== remaining) {
    remaining = secondsLeft;
    updateDisplay();
  }
  if (secondsLeft <= 0) {
    stopTimer();
    remaining = 0;
    updateDisplay();
    startPauseBtn.textContent = 'START';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
  }
}

function startTimer() {
  if (running) return;
  if (remaining <= 0) {
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    updateDisplay();
  }
  running = true;
  endTime = Date.now() + remaining * 1000;
  intervalId = setInterval(tick, 200);
  startPauseBtn.textContent = 'PAUSE';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
}

function pauseTimer() {
  if (!running) return;
  running = false;
  clearInterval(intervalId);
  intervalId = null;
  remaining = Math.max(0, Math.round((endTime - Date.now()) / 1000));
  updateDisplay();
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function stopTimer() {
  running = false;
  if (intervalId) {
    clearInterval(intervalId);
    intervalId = null;
  }
}

function resetTimer() {
  stopTimer();
  remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
  updateDisplay();
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

startPauseBtn.addEventListener('click', () => {
  if (running) {
    pauseTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);

workModeBtn.addEventListener('click', () => setMode('work'));
breakModeBtn.addEventListener('click', () => setMode('break'));

document.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'BUTTON') return;
  if (e.code === 'Space') {
    e.preventDefault();
    if (running) pauseTimer(); else startTimer();
  } else if (e.key === 'r' || e.key === 'R') {
    resetTimer();
  }
});

updateDisplay();
